mapper.select:
SELECT d.id, d.user_id AS userId, d.title, d.content, d.score, d.status, d.resolver_id AS resolverId, d.adopt_reply_id AS adoptReplyId, d.resolve_time AS resolveTime, d.create_time AS createTime, d.update_time AS updateTime, u.username AS authorName, u.avatar AS authorAvatar, COALESCE(dr.reply_count, 0) AS replyCount FROM demand d LEFT JOIN `user` u ON d.user_id = u.id LEFT JOIN ( SELECT demand_id, COUNT(*) AS reply_count FROM demand_reply WHERE deleted = 0 GROUP BY demand_id ) dr ON d.id = dr.demand_id WHERE d.deleted = 0
AND d.status = #{status}
ORDER BY d.create_time DESC
